param([Parameter(Mandatory)][ValidateSet('qa-bootstrap','qa-run-plan','qa-report-verify','qa-complete','qa-receipt','qa-status','qa-catalog','qa-catalog-dry-run','qa-help','qa-capabilities')][string]$Operation,[string]$StoreRoot,[string]$TaskId,[string]$WorkflowId,[string]$QaWorkflowId,[string]$RunId,[string]$ReportPath,[switch]$DryRun)
$ErrorActionPreference='Stop'; $WarningPreference='SilentlyContinue'; Import-Module (Join-Path $PSScriptRoot 'Repato.AgentOrchestration.psm1') -Force -WarningAction SilentlyContinue; Import-Module (Join-Path $PSScriptRoot 'Repato.Deployment.v4.psm1') -Force -WarningAction SilentlyContinue; Import-Module (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Force -WarningAction SilentlyContinue
try { $result = switch($Operation){'qa-bootstrap'{New-MayaQaBootstrap $QaWorkflowId $RunId $StoreRoot $TaskId -DryRun:$DryRun};'qa-run-plan'{New-MayaQaRun $StoreRoot $TaskId $WorkflowId $QaWorkflowId $RunId -DryRun:$DryRun};'qa-report-verify'{Register-MayaQaReport $StoreRoot $TaskId $WorkflowId $QaWorkflowId $ReportPath -DryRun:$DryRun};'qa-complete'{Complete-MayaQaWorkflow $StoreRoot $TaskId $WorkflowId -DryRun:$DryRun};'qa-receipt'{New-MayaQaReceipt $StoreRoot $TaskId $WorkflowId -DryRun:$DryRun};'qa-status'{Get-MayaQaWorkflowStatus $StoreRoot $TaskId $WorkflowId};'qa-catalog'{Get-MayaQaWorkflowCatalog};'qa-catalog-dry-run'{Get-MayaQaCatalogDryRun $WorkflowId};'qa-help'{[pscustomobject]@{Operations=@('qa-bootstrap','qa-run-plan','qa-report-verify','qa-complete','qa-receipt','qa-status','qa-catalog','qa-catalog-dry-run','qa-help','qa-capabilities');SupervisedExecutionRequired=$true;RevitLaunchByCoordinator=$false;RealDeploymentByCoordinator=$false;DryRunSupported=$true;WorkflowIds=@(Get-MayaQaWorkflowCatalog|ForEach-Object WorkflowId)}};'qa-capabilities'{Get-MayaQaWorkflowCatalog}}; $result|ConvertTo-Json -Compress -Depth 12 } catch { [Console]::Error.WriteLine($_.Exception.Message); exit 1 }
